# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple
from rosterkit.models import Student

def check_emails(students: List[Student]) -> None:
    """Reject an empty list or a missing email."""
    if not students:
        raise ValueError("no students to list")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ValueError(f"no email on file for {name}")

def column_widths(
    students: List[Student]
) -> Tuple[int, int]:
    names = [item.display_name for item in students]
    sections = [item.section for item in students]
    return max(map(len, names)), max(map(len, sections))

def format_contact(
    student: Student, name_width: int, section_width: int
) -> str:
    name = student.display_name.ljust(name_width)
    section = student.section.ljust(section_width)
    return f"{name}  {section}  {student.email}"

def contact_rows(students: Iterable[Student]) -> List[str]:
    """One aligned text row per student, sorted by name."""
    roster = sorted(students, key=lambda s: s.display_name)
    check_emails(roster)
    widths = column_widths(roster)
    return [
        format_contact(item, *widths) for item in roster
    ]
